// Tudo chega como texto (o app manda formulário simples).
const corpo = $('Recebe pedido do app').first().json.body || {};
const texto = (v) => String(v ?? '').trim();
const CAMPOS = ["Placa","Marca_Modelo","Especie_Tipo","Carroceria","Categoria","Cor","Combustivel","Ano_Fabricacao","Ano_Modelo","Renavam","Chassi","Motor","Numero_CRV","Codigo_Seguranca_CLA","CAT","Placa_Anterior","Potencia_Cilindrada","Capacidade","Lotacao","Peso_Bruto_Total","CMT","Eixos","Proprietario_Nome","Proprietario_Documento","Local","Data_Documento","Exercicio","Observacoes"];
const ACOES = ['carregar', 'salvar', 'documento', 'remover-documento', 'consumo', 'pneu'];
const acao = ACOES.includes(texto(corpo.acao)) ? texto(corpo.acao) : '';
let erro = acao ? '' : 'Ação inválida.';

// Campos: JSON { Campo: "valor" }. Só os conhecidos; texto curto.
let campos = {};
if (!erro && (acao === 'salvar' || acao === 'documento')) {
  let bruto = {};
  try { bruto = JSON.parse(texto(corpo.campos) || '{}'); } catch (e) { erro = 'Dados do veículo inválidos.'; }
  if (bruto && typeof bruto === 'object' && !Array.isArray(bruto)) {
    for (const c of CAMPOS) {
      if (Object.prototype.hasOwnProperty.call(bruto, c)) {
        campos[c] = String(bruto[c] ?? '').replace(/\s+/g, c === 'Observacoes' ? ' ' : ' ').trim().slice(0, c === 'Observacoes' ? 1000 : 200);
      }
    }
  }
}

// Consumo (km/l), digitado pelo dono. Vazio = excluir.
let consumo = null;
if (!erro && acao === 'consumo') {
  const bruto = texto(corpo.consumo).replace(/\s+/g, '').replace(',', '.');
  if (bruto) {
    const n = Number(bruto);
    if (!/^\d{1,2}(\.\d{1,2})?$/.test(bruto) || !(n > 0 && n < 100)) erro = 'Consumo inválido. Use só o número de km por litro, por exemplo 9,5.';
    else consumo = n;
  }
}

// Pneu (09/11/2026): uma das 5 posições. Tudo vazio = excluir o pneu.
const POSICOES = ["Dianteiro esquerdo","Dianteiro direito","Traseiro esquerdo","Traseiro direito","Estepe"];
let pneu = null;
if (!erro && acao === 'pneu') {
  // Número em reais/decimal: vazio -> null; inválido -> NaN. "1.234,56" e "450.5" valem.
  const num = (v, re) => {
    let s = texto(v).replace(/\s+/g, '').replace(/^R\$/i, '');
    if (!s) return null;
    if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
    return re.test(s) ? Number(s) : NaN;
  };
  const posicao = texto(corpo.posicao);
  const marca = texto(corpo.marca).replace(/\s+/g, ' ').slice(0, 80);
  const modelo = texto(corpo.modelo).replace(/\s+/g, ' ').slice(0, 80);
  const valor = num(corpo.valor, /^\d{1,7}(\.\d{1,2})?$/);
  const desgaste = num(corpo.desgaste, /^\d{1,3}(\.\d{1,4})?$/);
  let data = texto(corpo.dataTroca);
  const br = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(data);
  if (br) data = br[3] + '-' + br[2] + '-' + br[1];
  const dataOk = !data || (/^\d{4}-\d{2}-\d{2}$/.test(data) && !isNaN(new Date(data + 'T12:00:00Z'))
    && new Date(data + 'T12:00:00Z').toISOString().slice(0, 10) === data && data >= '2000-01-01' && data <= '2100-12-31');
  if (!POSICOES.includes(posicao)) erro = 'Pneu inválido.';
  else if (Number.isNaN(valor)) erro = 'Valor pago inválido. Use só o número, por exemplo 450,00.';
  else if (Number.isNaN(desgaste)) erro = 'Desgaste inválido. Use só o número de reais por km, por exemplo 0,009.';
  else if (!dataOk) erro = 'Data da troca inválida.';
  else pneu = { posicao, marca, modelo, valor, data: data || null, desgaste,
    vazio: !marca && !modelo && valor === null && !data && desgaste === null };
}

// Documento: PDF em base64, até uns 8 MB.
let arquivo = '';
let nomeArquivo = '';
if (!erro && acao === 'documento') {
  arquivo = texto(corpo.arquivo).replace(/^data:[^,]*,/, '');
  nomeArquivo = texto(corpo.nomeArquivo).replace(/[\\/:*?"<>|\x00-\x1f]/g, '_').slice(0, 150) || 'documento-do-veiculo.pdf';
  if (!/\.pdf$/i.test(nomeArquivo)) nomeArquivo += '.pdf';
  if (!arquivo || !/^[A-Za-z0-9+/=]+$/.test(arquivo)) erro = 'Arquivo inválido.';
  else if (!arquivo.startsWith('JVBERi0')) erro = 'O arquivo precisa ser um PDF.';
  else if (arquivo.length > 11 * 1024 * 1024) erro = 'O PDF passa de 8 MB. Tente um arquivo menor.';
}
return [{ json: { acao, campos, consumo, pneu, arquivo, nomeArquivo, erro } }];

// Um veículo só, por enquanto: o primeiro (e único) registro da tabela.
const e = $('Le entrada').first().json;
const registros = ($('Busca veículo').first().json.records || []);
const atual = registros[0] || null;
const pneus = ($json.records || []);
const URL_TABELA = 'http://127.0.0.1:5690/v0/app6PyYmtFduIMp7B/tblVeiculosFrota1';
const URL_PNEUS = 'http://127.0.0.1:5690/v0/app6PyYmtFduIMp7B/tblPneusVeiculo01';
let grava = false, metodo = '', url = '', corpo = null;
if (e.acao === 'pneu') {
  const p = e.pneu;
  const existente = pneus.find((r) => (r.fields || {}).Posicao === p.posicao);
  if (p.vazio) {
    // Excluir: apaga o pneu daquela posição (se houver).
    if (existente) { grava = true; metodo = 'DELETE'; url = URL_PNEUS + '/' + existente.id; corpo = {}; }
  } else {
    grava = true;
    const fields = { Posicao: p.posicao, Marca: p.marca || null, Modelo: p.modelo || null, Valor_Pago: p.valor,
      Data_Troca: p.data, Desgaste_R_Km: p.desgaste };
    if (existente) { metodo = 'PATCH'; url = URL_PNEUS + '/' + existente.id; corpo = { fields }; }
    else { metodo = 'POST'; url = URL_PNEUS; corpo = { fields }; }
  }
}
if (e.acao === 'salvar' || e.acao === 'documento') {
  const fields = { ...e.campos };
  // Documento novo substitui o antigo (o arquivo antigo continua na pasta de anexos do PC).
  if (e.acao === 'documento') fields.Documento = [];
  grava = true;
  if (atual) { metodo = 'PATCH'; url = URL_TABELA + '/' + atual.id; corpo = { fields }; }
  else { metodo = 'POST'; url = URL_TABELA; corpo = { fields }; }
} else if (e.acao === 'consumo') {
  grava = true;
  const fields = { Consumo_Km_L: e.consumo };
  if (atual) { metodo = 'PATCH'; url = URL_TABELA + '/' + atual.id; corpo = { fields }; }
  else { metodo = 'POST'; url = URL_TABELA; corpo = { fields }; }
} else if (e.acao === 'remover-documento' && atual) {
  grava = true; metodo = 'PATCH'; url = URL_TABELA + '/' + atual.id; corpo = { fields: { Documento: [] } };
}
return [{ json: { grava, metodo, url, corpo, sobe: e.acao === 'documento' } }];

const e = $('Le entrada').first().json;
const id = $json.id || (($json.records || [])[0] || {}).id;
return [{ json: {
  url: 'http://127.0.0.1:5690/v0/app6PyYmtFduIMp7B/' + id + '/Documento/uploadAttachment',
  corpo: { contentType: 'application/pdf', file: e.arquivo, filename: e.nomeArquivo },
} }];

// Anexo guardado no PC vem com endereço relativo (/webhook/anexo...): completa com o
// endereço por onde o app chegou (o túnel), senão o PDF não abre no celular.
const cab = $('Recebe pedido do app').first().json.headers || {};
const origem = String(cab['x-forwarded-proto'] || 'http').split(',')[0].trim() + '://' + (cab['x-forwarded-host'] || cab.host || 'localhost:5678');
const urlAnexo = (u) => (String(u || '').startsWith('/') ? origem + u : u);
const CAMPOS = ["Placa","Marca_Modelo","Especie_Tipo","Carroceria","Categoria","Cor","Combustivel","Ano_Fabricacao","Ano_Modelo","Renavam","Chassi","Motor","Numero_CRV","Codigo_Seguranca_CLA","CAT","Placa_Anterior","Potencia_Cilindrada","Capacidade","Lotacao","Peso_Bruto_Total","CMT","Eixos","Proprietario_Nome","Proprietario_Documento","Local","Data_Documento","Exercicio","Observacoes"];
const POSICOES = ["Dianteiro esquerdo","Dianteiro direito","Traseiro esquerdo","Traseiro direito","Estepe"];
const reg = ($('Busca de novo').first().json.records || [])[0] || null;
const numero = (v) => (v === null || v === undefined || v === '' ? null : Number(v));
const salvos = ($json.records || []).map((r) => r.fields || {});
const pneus = POSICOES.map((posicao) => {
  const f = salvos.find((s) => s.Posicao === posicao);
  return f ? { posicao, salvo: true, marca: f.Marca || '', modelo: f.Modelo || '', valor: numero(f.Valor_Pago),
    dataTroca: f.Data_Troca ? String(f.Data_Troca).slice(0, 10) : '', desgaste: numero(f.Desgaste_R_Km) }
    : { posicao, salvo: false, marca: '', modelo: '', valor: null, dataTroca: '', desgaste: null };
});
let veiculo = null;
if (reg) {
  const f = reg.fields || {};
  const campos = {};
  for (const c of CAMPOS) campos[c] = f[c] || '';
  const doc = (f.Documento || [])[0] || null;
  const consumo = typeof f.Consumo_Km_L === 'number' ? f.Consumo_Km_L : (f.Consumo_Km_L ? Number(f.Consumo_Km_L) : null);
  veiculo = { id: reg.id, campos, consumo, documento: doc ? { nome: doc.filename, url: urlAnexo(doc.url), tamanho: doc.size || 0 } : null };
}
const acao = $('Le entrada').first().json.acao;
const consumoNovo = $('Le entrada').first().json.consumo;
const pneuNovo = $('Le entrada').first().json.pneu;
const MSG = { consumo: consumoNovo === null ? 'Consumo excluído.' : 'Consumo salvo.', salvar: 'Salvo.', documento: 'Documento anexado.', 'remover-documento': 'Documento removido.',
  pneu: pneuNovo && pneuNovo.vazio ? 'Pneu excluído.' : 'Pneu salvo.' };
return [{ json: { ok: true, veiculo, pneus, mensagem: MSG[acao] || '' } }];
